// Joins src/*.js into the deliverables:
//   dist/web/index.html                 standalone page for playtesting
//   dist/artifact/hermes-arena.html     the same game for an Artifact page
//   dist/book/index.html                animation book (+ dist/artifact/hermes-animations.html)
//   dist/hermes-arena/plugin.js         Hermes Desktop plugin (drop into ~/.hermes/desktop-plugins/)
// Usage: node build.mjs [--out <dir>]   (default dist; a separate dir lets several
// people build at once without overwriting each other's pages)
// Skins: src/skins.js plus every src/skins/*.js (GENERATED by tools/build-skins.mjs
// from concepts/cutout/<key>/skin.js; images inline as data URIs).
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
// animation files (one per move group) load after the registry and before the game
const animFiles = existsSync(join(root, 'src/anims'))
  ? readdirSync(join(root, 'src/anims')).filter((f) => f.endsWith('.js')).sort().map((f) => 'anims/' + f)
  : [];
// skin modules (one per puppet) load after the animations, before the game
const skinFiles = existsSync(join(root, 'src/skins'))
  ? readdirSync(join(root, 'src/skins')).filter((f) => f.endsWith('.js')).sort().map((f) => 'skins/' + f)
  : [];
const ORDER = ['core.js', 'art.js', 'stage.js', 'figure.js', 'anim.js', 'skins.js', ...animFiles, ...skinFiles, 'fighter.js', 'match.js', 'game.js'];
const src = (f) => `// ==== src/${f} ====\n` + readFileSync(join(root, 'src', f), 'utf8');
const engine = ORDER.map(src).join('\n');
const bookEngine = ['core.js', 'art.js', 'figure.js', 'anim.js', 'skins.js', ...animFiles, ...skinFiles, 'viewer.js'].map(src).join('\n');
// warn when a generated skin is older than its template or puppet
for (const f of skinFiles) {
  const key = f.slice(6, -3);
  const t = statSync(join(root, 'src', f)).mtimeMs;
  for (const dep of [`concepts/cutout/${key}/skin.js`, `concepts/cutout-${key}.js`]) {
    if (existsSync(join(root, dep)) && statSync(join(root, dep)).mtimeMs > t + 1) {
      console.warn(`warning: src/${f} is older than ${dep}; run: node tools/build-skins.mjs ${key}`);
    }
  }
}
const outArg = process.argv.indexOf('--out');
const OUT = outArg > 0 && process.argv[outArg + 1] ? resolve(process.argv[outArg + 1]) : join(root, 'dist');
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
const banner = `/* Hermes Arena v${pkg.version} — original platform fighter. All art is generated in code. */\n`;

// ---- web build ---------------------------------------------------------------
const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Hermes Arena</title>
<style>
  :root { --paper: #edf1f5; --ink: #2443a8; }
  html, body { margin: 0; height: 100%; background: var(--paper); overflow: hidden; }
  #arena { position: fixed; inset: 0; }
</style>
</head>
<body>
<div id="arena"></div>
<script>
${banner}${engine}
const params = new URLSearchParams(location.search);
window.__arena = createArena(document.getElementById('arena'), { debug: params.has('debug') });
</script>
</body>
</html>
`;
mkdirSync(join(OUT, 'web'), { recursive: true });
writeFileSync(join(OUT, 'web/index.html'), html);

// ---- artifact page (same game, wrapped by the Artifact skeleton) -------------
const artifact = `<title>Hermes Arena</title>
<meta name="claude:viewport-fit-sides" content="cover">
<style>
  /* Single look on purpose: blue ink on parchment, in either host theme. */
  :root { --paper: #edf1f5; --ink: #2443a8; color-scheme: light; }
  html, body { height: 100%; margin: 0; background: var(--paper); color: var(--ink); overflow: hidden; }
  #arena { position: fixed; inset: env(safe-area-inset-top, 0px) env(safe-area-inset-right, 0px) env(safe-area-inset-bottom, 0px) env(safe-area-inset-left, 0px); }
</style>
<div id="arena" role="application" aria-label="Hermes Arena game. Click to play, then use the keyboard."></div>
<script>
${banner}${engine}
createArena(document.getElementById('arena'), {});
</script>
`;
mkdirSync(join(OUT, 'artifact'), { recursive: true });
writeFileSync(join(OUT, 'artifact/hermes-arena.html'), artifact);

// ---- animation book (viewer) --------------------------------------------------
const FONTS = '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' +
  '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=EB+Garamond:wght@400;500&family=IBM+Plex+Mono:wght@400;500;600&family=Marcellus+SC&display=swap">';
const bookBody = `<div id="book" style="height:100%"></div>
<script>
${banner}${bookEngine}
window.__book = createAnimBook(document.getElementById('book'), { char: 'hermes' });
</script>`;
mkdirSync(join(OUT, 'book'), { recursive: true });
writeFileSync(join(OUT, 'book/index.html'), `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Hermes Animation Book</title>${FONTS}
<style>html,body{height:100%;margin:0;background:#e6e9e6}</style>
</head><body>${bookBody}
<script>document.head.insertAdjacentHTML('beforeend', '<style>' + ANIM_BOOK_CSS + '</style>');</script>
</body></html>
`);
writeFileSync(join(OUT, 'artifact/hermes-animations.html'), `<title>Hermes Animation Book</title>
<meta name="claude:viewport-fit-sides" content="cover">
${FONTS}
<style>
  /* Single look on purpose: blue ink on parchment, in either host theme. */
  :root { --page: #e6e9e6; color-scheme: light; }
  html, body { height: 100%; margin: 0; background: var(--page); color: #0e2566; }
</style>
${bookBody}
<script>document.head.insertAdjacentHTML('beforeend', '<style>' + ANIM_BOOK_CSS + '</style>');</script>
`);

// ---- Hermes Desktop plugin ---------------------------------------------------
const plugin = `${banner}// Install: copy this folder to ~/.hermes/desktop-plugins/hermes-arena/
import { useEffect, useRef } from 'react';
import { jsx } from 'react/jsx-runtime';

${engine}

function ArenaPage() {
  const ref = useRef(null);
  useEffect(() => {
    if (!ref.current) return undefined;
    const arena = createArena(ref.current, { storage: PLUGIN_STORAGE });
    return () => arena.destroy();
  }, []);
  return jsx('div', {
    style: { position: 'relative', flex: '1 1 auto', width: '100%', height: '100%', minHeight: 0 },
    children: jsx('div', {
      ref,
      style: { position: 'absolute', inset: 0, overflow: 'hidden', background: '#edf1f5' },
    }),
  });
}

let PLUGIN_STORAGE = null;

export default {
  id: 'hermes-arena',
  name: 'Hermes Arena',
  register(ctx) {
    PLUGIN_STORAGE = ctx.storage || null;
    ctx.registerMany([
      { id: 'page', area: 'routes', data: { path: '/hermes-arena' }, render: () => jsx(ArenaPage, {}) },
      { id: 'nav', area: 'sidebar.nav', data: { path: '/hermes-arena', label: 'Hermes Arena', codicon: 'game' } },
    ]);
  },
};
`;
mkdirSync(join(OUT, 'hermes-arena'), { recursive: true });
writeFileSync(join(OUT, 'hermes-arena/plugin.js'), plugin);
console.log('built', (html.length / 1024).toFixed(1) + 'KB web,', (plugin.length / 1024).toFixed(1) + 'KB plugin');
